# assets/css/styles.css
@'\n:root{\n  --bg:#0f1724;\n  --card:#0b1220;\n  --muted:#a8b3c5;\n  --accent:#ffb347;\n  --accent-2:#ff7a59;\n  --white:#ffffff;\n  --max-width:1100px;\n}\n*{box-sizing:border-box}\nbody{font-family:Inter,Segoe UI,Arial,Helvetica,sans-serif;margin:0;background:linear-gradient(180deg,#071026 0%, #071a2b 100%);color:var(--white);line-height:1.5}\n.container{max-width:var(--max-width);margin:0 auto;padding:1.25rem}\n.site-header{background:transparent;padding:.75rem 0}\n.header-inner{display:flex;align-items:center;justify-content:space-between}\n.brand{font-weight:700;color:var(--white);text-decoration:none}\n.main-nav ul{list-style:none;margin:0;padding:0;display:flex;gap:1rem}\n.main-nav a{color:var(--muted);text-decoration:none}\n.nav-toggle{display:none}\n.hero{padding:4rem 0;text-align:center}\n.hero .lead{color:var(--muted);max-width:42rem;margin:0 auto 1rem}\n.btn{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#111;padding:.6rem 1rem;border-radius:8px;border:none;text-decoration:none;cursor:pointer}\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin-top:1rem}\n.card{background:rgba(255,255,255,0.03);padding:1rem;border-radius:10px}\n.card img{width:100%;height:140px;object-fit:cover;border-radius:6px}\n.about-preview{background:rgba(255,255,255,0.01);padding:1.5rem;border-radius:10px;margin:2rem 0}\n.site-footer{background:rgba(0,0,0,0.25);padding:1rem 0;margin-top:2rem}\n.footer-inner{display:flex;flex-wrap:wrap;gap:1rem;align-items:flex-start;justify-content:space-between}\n.footer-contact{min-width:260px}\nfooter label{display:block;font-size:.85rem;margin-top:.5rem}\nfooter input,footer textarea{width:100%;padding:.5rem;border-radius:6px;border:1px solid rgba(255,255,255,0.06);background:transparent;color:var(--white)}\n.feedback{margin-top:.5rem;color:var(--accent)}\n.portfolio-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:1rem}\n.project{background:rgba(255,255,255,0.02);padding:1rem;border-radius:8px}\n.project img{width:100%;height:180px;object-fit:cover;border-radius:6px}\n.view-btn{margin-top:.5rem;background:transparent;border:1px solid var(--accent);color:var(--accent);padding:.4rem .6rem;border-radius:6px;cursor:pointer}\n.modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,0.6);}\n.modal[aria-hidden=\"false\"]{display:flex}\n.modal-content{background:var(--card);padding:1rem;border-radius:10px;max-width:900px;width:95%;color:var(--muted)}\n.modal-close{background:transparent;border:0;color:var(--accent);cursor:pointer}\n@media (max-width:700px){\n  .main-nav{display:none}\n  .nav-toggle{display:inline-block}\n  .footer-inner{flex-direction:column}\n}\n'@ | Out-File -FilePath \"$root\\assets\\css\\styles.css\" -Encoding utf8

# assets/js/main.js
@'\n// Simple interactions: nav toggle, year, contact form handling, modal\n(function(){\n  // year\n  var y = new Date().getFullYear();\n  [\"year\",\"year-2\",\"year-3\",\"year-4\"].forEach(function(id){\n    var el = document.getElementById(id);\n    if(el) el.textContent = y;\n  });\n\n  // nav toggle\n  var navToggles = document.querySelectorAll('.nav-toggle');\n  navToggles.forEach(function(btn){\n    var target = btn.getAttribute('aria-controls');\n    btn.addEventListener('click', function(){\n      var nav = document.getElementById(target) || document.querySelector('.main-nav');\n      var expanded = btn.getAttribute('aria-expanded') === 'true';\n      btn.setAttribute('aria-expanded', (!expanded).toString());\n      if(nav) nav.style.display = expanded ? 'none' : 'block';\n    });\n  });\n\n  // footer contact forms - fake submit\n  function bindContact(idForm,idFeedback){\n    var form = document.getElementById(idForm);\n    if(!form) return;\n    var feedback = document.getElementById(idFeedback);\n    form.addEventListener('submit', function(e){\n      e.preventDefault();\n      var name = form.querySelector('[name=\"name\"]').value.trim();\n      var email = form.querySelector('[name=\"email\"]').value.trim();\n      var msg = (form.querySelector('[name=\"message\"]')||{value:''}).value.trim();\n      if(!name || !email || !msg){\n        feedback.textContent = 'Veuillez remplir tous les champs.'; return;\n      }\n      feedback.textContent = 'Merci — message simulé envoyé.';\n      form.reset();\n      setTimeout(function(){ feedback.textContent = ''; },3000);\n    });\n  }\n  bindContact('footer-contact-form','contact-feedback');\n  bindContact('footer-contact-form-2','contact-feedback-2');\n  bindContact('footer-contact-form-3','contact-feedback-3');\n  bindContact('contact-page-form','contact-page-feedback');\n\n  // Project modal\n  var modal = document.getElementById('project-modal');\n  var modalBody = document.getElementById('modal-body');\n  var closeBtn = document.getElementById('modal-close');\n  function openModal(content){\n    if(!modal) return;\n    modalBody.innerHTML = content;\n    modal.setAttribute('aria-hidden','false');\n  }\n  function closeModal(){ if(!modal) return; modal.setAttribute('aria-hidden','true'); }\n  document.querySelectorAll('.view-btn').forEach(function(btn){\n    btn.addEventListener('click', function(){\n      var id = btn.getAttribute('data-project');\n      var content = '<h2>Projet '+id+'</h2><p>Présentation du projet, défis, solutions UX et captures d\\'écran.</p>';\n      openModal(content);\n    });\n  });\n  if(closeBtn) closeBtn.addEventListener('click', closeModal);\n  if(modal) modal.addEventListener('click', function(e){ if(e.target === modal) closeModal(); });\n})();\n'@ | Out-File -FilePath \"$root\\assets\\js\\main.js\" -Encoding utf8

# README.md
@'\n# Portfolio — Jeune Artiste Africain\n\nSite statique (HTML/CSS/JS) pour présenter des réalisations UX/UI.\n\nAperçu des fichiers créés :\n- `index.html` — page d'accueil\n- `portfolio.html` — liste des projets\n- `about.html` — page À propos\n- `contact.html` — page de contact\n- `assets/css/styles.css` — styles responsives\n- `assets/js/main.js` — interactions (nav, modal, validation form)\n- `assets/img/` — répertoire pour vos images (ajoutez vos fichiers ici)\n\nPour prévisualiser : ouvrir `index.html` dans un navigateur (double-clic). Pour développement plus avancé, utilisez un serveur local (ex : `python -m http.server 8000` dans le dossier) si vous souhaitez éviter les blocages relatifs aux chemins ou modules.\n\nRemarques :\n- Le formulaire de contact simule un envoi côté client; ajoutez un backend ou service d'email (Formspree, Netlify Forms, etc.) pour réception réelle.\n- Remplacez les images placeholder dans `assets/img` par vos maquettes/exports.\n'@ | Out-File -FilePath \"$root\\README.md\" -Encoding utf8

